head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 모든 케이스가 공통으로 사용하는 saveList
scwin.SAVE_LIST = ["c2", "c0"];



// 케이스 실행
//  · 다운로드 파일이 서로 구분되도록 파일명에 케이스 번호와 클릭 시점의 Column 표시 순서를 넣는다.
scwin.runCase = function (strNo, bColumnMove) {
    var arrOrder = target1.getColumnOrder(true);

    var objOptions = { saveList : scwin.SAVE_LIST, delim : "," };
    if (bColumnMove === true) objOptions.columnMove = "true";
    objOptions.fileName = "saveCSV_case" + strNo + "_" + arrOrder.join("-") + ".csv";

    target1.saveCSV(objOptions);

    scwin.setReturnValue("[" + strNo + "] options = " + JSON.stringify(objOptions));
    scwin.setReturnValue("[" + strNo + "] getColumnOrder(true) = " + JSON.stringify(arrOrder));
    scwin.setReturnValue("");
};



// ① 이동 전 저장 (saveList + columnMove:"true")
scwin.btn_case1_onclick = function () {
    scwin.runCase("1", true);
};

// ② Column 이동 (c0 을 맨 뒤로)
scwin.btn_case2_onclick = function () {
    target1.moveColumnByHeaderId("h0", "h4");
    scwin.setReturnValue("[2] moveColumnByHeaderId(\"h0\", \"h4\")");
    scwin.setReturnValue("[2] getColumnOrder(true) = " + JSON.stringify(target1.getColumnOrder(true)));
    scwin.setReturnValue("");
};

// ③ 이동 후 저장 (columnMove 미설정)
scwin.btn_case3_onclick = function () {
    scwin.runCase("3", false);
};

// ④ 이동 후 저장 (columnMove:"true")
scwin.btn_case4_onclick = function () {
    scwin.runCase("4", true);
};
